class Solution {
public:
    int minOperations(string s) {
        int n = s.size(), ans = INT_MAX;
        for (int rot = 0; rot < n; ++rot) {
            int cost = rot;
            for (int i = 0; i < n / 2; ++i) {
                int a = s[(rot + i) % n] - 'a';
                int b = s[(rot + n - 1 - i) % n] - 'a';
                int d = abs(a - b);
                cost += min(d, 26 - d);
            }
            ans = min(ans, cost);
        }
        return ans;
    }
};
